const travelData={
 mexico:{airports:[['MEX','Mexico City'],['CUN','Cancún'],['GDL','Guadalajara'],['SJD','Los Cabos']],base:650,hours:5,costs:[100,35,18,20],regions:[['Cancún / Yucatán','BBBAAAWWWWAB'],['Mexico City / central highlands','BBBBAAAAWABB'],['Oaxaca','BBBBAAWWAABB'],['Puerto Vallarta / Pacific coast','BBBBAWWWWWAB'],['Los Cabos','BBBAAWWAAABB']]},
 japan:{airports:[['HND','Tokyo Haneda'],['NRT','Tokyo Narita'],['KIX','Osaka Kansai'],['FUK','Fukuoka']],base:1400,hours:13,costs:[130,45,25,25],regions:[['Tokyo / Kyoto / Osaka','AABBBWWWBBBA'],['Hokkaido','AAAWABBBBAAA'],['Okinawa','AABBBAWWWAAB']]},
 portugal:{airports:[['LIS','Lisbon'],['OPO','Porto'],['FAO','Faro'],['PDL','Ponta Delgada']],base:950,hours:8,costs:[110,40,18,20],regions:[['Lisbon / central coast','AAABBBBABBAA'],['Porto / north','WWAABBBBBAAW'],['Algarve','AAABBBBABBAA'],['Madeira','AABBBBBBBBAA'],['Azores','WAAABBBBBAAW']]},
 thailand:{airports:[['BKK','Bangkok Suvarnabhumi'],['HKT','Phuket'],['CNX','Chiang Mai'],['USM','Koh Samui']],base:1600,hours:22,costs:[65,25,15,18],regions:[['Bangkok / central Thailand','BBAAWWWWWWBB'],['Chiang Mai / north','BAWWAAWWWABB'],['Phuket / Andaman coast','BBBAWWWWWWAB'],['Koh Samui / Gulf coast','ABBBBAAAAAWW']]}
};
const departureCities=[['YYZ','Toronto'],['YVR','Vancouver'],['YUL','Montréal'],['YYC','Calgary'],['YEG','Edmonton']];
let guideDeparture='YYZ';
function renderTravelDetail(key,kind){
 const panel=document.querySelector('.detail-panel'),d=travelData[key],name=countries[key].name;
 panel.hidden=false;
 if(kind==='flights'){
 panel.innerHTML=`<h3>Flights and routing</h3><p class="estimate-note">Illustrative CAD round-trip economy allowances and one-way journey times, to be confirmed. These are not current fares, schedules or ranked live results. Enter your dates in the linked flight search to compare actual options.</p><label>Departure city <select id="departure-city">${departureCities.map(([code,n])=>`<option value="${code}" ${code===guideDeparture?'selected':''}>${n} (${code})</option>`).join('')}</select></label><div id="route-results"></div>`;
 const update=()=>{guideDeparture=panel.querySelector('select').value;const i=departureCities.findIndex(r=>r[0]===guideDeparture);const asia=['japan','thailand'].includes(key);const delta=asia?[0,-200,100,120,180][i]:[0,180,30,130,200][i];const dt=asia?[0,-3,1,1,2][i]:[0,3,0,2,3][i];
 const routes=d.airports.map(([code,city],j)=>({code,city,price:d.base+delta+j*110,time:d.hours+dt+j*1.5})).sort((a,b)=>a.price-b.price);
 panel.querySelector('#route-results').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Arrival hub</th><th>Sample return CAD</th><th>Sample journey</th><th>Dates & fares</th></tr></thead><tbody>${routes.map(r=>`<tr><td>${r.city} (${r.code})</td><td>$${r.price}</td><td>~${r.time} h</td><td><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/travel/flights?q=${encodeURIComponent('round trip flights '+guideDeparture+' to '+r.code)}">Search ↗</a></td></tr>`).join('')}</tbody></table></div><p>Connections, season and baggage can change the total considerably.</p>`;};panel.querySelector('select').onchange=update;update();
 }else if(kind==='season'){
 panel.innerHTML=`<h3>Best time to go</h3><p class="estimate-note">Draft seasonal guide — classifications to be confirmed against regional climate sources. BEST = generally milder/drier sightseeing conditions; AVERAGE = mixed conditions; WORST = less favourable heat, rain or cold for general sightseeing. This is not a safety forecast or a rating for skiing, festivals or every activity.</p><div class="table-scroll"><table class="season-table"><thead><tr><th>Region</th>${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].map(m=>`<th>${m}</th>`).join('')}</tr></thead><tbody>${d.regions.map(([region,months])=>`<tr><th>${region}</th>${[...months].map(c=>{const text={B:'BEST',A:'AVERAGE',W:'WORST'}[c];return `<td class="${text.toLowerCase()}">${text}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p><a href="https://climateknowledgeportal.worldbank.org/" target="_blank" rel="noopener noreferrer">Explore World Bank climate data ↗</a></p>`;
 }else if(kind==='insurance'){
 panel.innerHTML=`<h3>Travel insurance</h3><p>Start with emergency medical cover, then assess trip cancellation, interruption and baggage cover against your bookings and existing benefits.</p><ul><li>Check medical evacuation and repatriation.</li><li>Confirm pre-existing condition and stability clauses in writing.</li><li>Check deductibles, activity exclusions, destination advisories and coverage for the full trip.</li><li>Check whether the insurer pays hospitals directly and offers 24-hour assistance.</li></ul><p class="estimate-note">Price requires a personal quote: age, health, destination, duration, deductible and coverage all matter. For this prototype only, allow CAD $5/day as a planning placeholder, not an insurer quote or coverage recommendation.</p><p><a href="https://travel.gc.ca/travelling/documents/travel-insurance" target="_blank" rel="noopener noreferrer">Government of Canada: choosing coverage ↗</a></p>`;
 }else{
 panel.innerHTML=`<h3>Budget and costs</h3><p class="estimate-note">Sample CAD allowances per person, to be confirmed. Accommodation assumes a private room/unit and varies substantially by city and season. Edit every amount to match your trip. Excludes insurance, visas and major paid activities.</p><label>Days <input id="trip-days" type="number" min="1" max="365" value="30"></label><label>Nights <input id="trip-nights" type="number" min="0" max="365" value="29"></label><table><thead><tr><th>Category</th><th>Basis</th><th>CAD allowance</th></tr></thead><tbody>${[['Flight in','one-time',Math.round(d.base/2)],['Accommodation','per night',d.costs[0]],['Food','per day',d.costs[1]],['Internal transport','per day',d.costs[2]],['Miscellaneous','per day',d.costs[3]]].map(([n,b,v],i)=>`<tr><td>${n}</td><td>${b}</td><td><input aria-label="${n} CAD" class="budget-rate" type="number" min="0" max="100000" value="${v}" style="width:85px"></td></tr>`).join('')}</tbody></table><output id="budget-total" aria-live="polite"></output>`;
 const update=()=>{const days=Math.max(1,Number(panel.querySelector('#trip-days').value)||1),nights=Math.max(0,Number(panel.querySelector('#trip-nights').value)||0),rates=[...panel.querySelectorAll('.budget-rate')].map(i=>Math.max(0,Number(i.value)||0));panel.querySelector('output').textContent='Estimated total: '+new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(rates[0]+rates[1]*nights+(rates[2]+rates[3]+rates[4])*days);};panel.querySelectorAll('input').forEach(i=>i.oninput=update);update();
 }
 panel.focus({preventScroll:true});panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});
}
